/**
 * test-ats-vector-pdf.mjs
 * End-to-end test verifying that the ATS vector PDF generated by resume-editor.js
 * produces a 100% extractable, valid resume document that passes validateResumeDocument
 * and analyseResumeLocally without any text parser or empty file errors.
 */
globalThis.window = {};
globalThis.document = { getElementById: () => null };
globalThis.navigator = { clipboard: { writeText: async () => {} } };

import { generateAtsVectorPdf } from './resume-editor.js';
import { validateResumeDocument, analyseResumeLocally } from './analysis-engine.js';

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (condition) {
    console.log(`  ✅ PASS: ${message}`);
    passed++;
  } else {
    console.error(`  ❌ FAIL: ${message}`);
    failed++;
  }
}

console.log('=== Running ATS Vector PDF Generator & Text Parser Verification ===\n');

const candidateData = {
  name: 'Saravan Prasanna',
  title: 'Full Stack Software Engineer',
  contact: 'saravan@example.com | +91 9876543210 | Chennai, Tamil Nadu | linkedin.com/in/saravan | github.com/wamender007-sara',
  summary: 'Motivated Full Stack Software Engineer with practical expertise in JavaScript, TypeScript, React, Node.js, and SQL. Dedicated to clean architecture and reliable web services.',
  skills: 'JavaScript, TypeScript, React, Node.js, Express.js, PostgreSQL, MongoDB, Git, Docker, REST APIs, HTML5, CSS3',
  experience: [
    {
      title: 'Full Stack Developer',
      company: 'Apex Tech Solutions',
      period: '2023 - Present',
      bullets: [
        'Architected and implemented responsive customer portal serving over 50,000 monthly active users.',
        'Engineered high-performance REST APIs reducing database query latency by 35% through indexing and caching.',
        'Spearheaded automated testing pipelines achieving 90%+ code coverage across critical microservices.'
      ]
    }
  ],
  projects: [
    {
      name: 'Resume Reviewer Platform',
      tools: 'React, Node.js, PDF.js',
      bullets: [
        'Built an in-browser ATS diagnostic engine performing deep linguistic and structural resume analysis.',
        'Integrated multi-format document parsing and automated candidate career benchmarking.'
      ]
    }
  ],
  education: [
    'B.E. Computer Science and Engineering - Anna University (2019 - 2023) - CGPA: 8.7/10'
  ],
  certifications: [
    'AWS Certified Solutions Architect - Associate (2024)',
    'Meta Front-End Developer Professional Certificate (2023)'
  ],
  achievements: [
    'Won 1st place in National Level Hackathon 2023 out of 120 participating teams.'
  ]
};

// 1. Generate Vector PDF
const pdfBytes = generateAtsVectorPdf(candidateData);
assert(pdfBytes instanceof Uint8Array, 'generateAtsVectorPdf returns Uint8Array binary data');
assert(pdfBytes.length > 2000, `PDF size is realistic (${pdfBytes.length} bytes, not empty)`);

// 2. Verify PDF Specification Header and Trailer
const decoder = new TextDecoder('latin1');
const pdfRaw = decoder.decode(pdfBytes);
assert(pdfRaw.startsWith('%PDF-1.4'), 'PDF starts with valid %PDF-1.4 header');
assert(pdfRaw.includes('%%EOF'), 'PDF ends with valid %%EOF trailer');
assert(pdfRaw.includes('/Type /Catalog'), 'PDF contains valid Catalog object');
assert(pdfRaw.includes('/Type /Pages'), 'PDF contains valid Pages tree');
assert(pdfRaw.includes('/Type /Page'), 'PDF contains valid Page object');
assert(pdfRaw.includes('/Font'), 'PDF contains font dictionary with Helvetica and Helvetica-Bold');

// 3. Extract Text Stream (simulating PDF.js line-based text extraction)
const streamMatches = [...pdfRaw.matchAll(/BT[\s\S]*?ET/g)];
assert(streamMatches.length > 0, `PDF stream contains ${streamMatches.length} text blocks`);

const textLines = [];
for (const block of streamMatches) {
  const tjMatches = [...block[0].matchAll(/\((.*?)\)\s*Tj/g)];
  for (const tm of tjMatches) {
    textLines.push(tm[1].replace(/\\\(/g, '(').replace(/\\\)/g, ')').replace(/\\\\/g, '\\'));
  }
}

const extractedResumeText = textLines.join('\n');
assert(extractedResumeText.includes('SARAVAN PRASANNA'), 'Extracted text contains candidate name in uppercase');
assert(extractedResumeText.includes('Full Stack Software Engineer'), 'Extracted text contains candidate title');
assert(extractedResumeText.includes('saravan@example.com'), 'Extracted text contains candidate email');
assert(extractedResumeText.includes('PROFESSIONAL SUMMARY:'), 'Extracted text contains PROFESSIONAL SUMMARY section');
assert(extractedResumeText.includes('TECHNICAL SKILLS:'), 'Extracted text contains TECHNICAL SKILLS section');
assert(extractedResumeText.includes('WORK EXPERIENCE:'), 'Extracted text contains WORK EXPERIENCE section');
assert(extractedResumeText.includes('KEY PROJECTS & TECHNICAL SYSTEMS:'), 'Extracted text contains PROJECTS section');
assert(extractedResumeText.includes('EDUCATION:'), 'Extracted text contains EDUCATION section');

// 4. Validate with ResumeReviewer Document Validator
const validation = validateResumeDocument(extractedResumeText, 'Saravan_Prasanna_Resume.pdf');
assert(validation.isValid === true, 'Document is verified as a valid Resume (isValid: true)');
assert(validation.isCertificate === false, 'Document is NOT misidentified as a certificate');
assert(validation.documentType === 'resume', 'Document type is identified as resume');
assert(validation.metrics.resumeSectionCount >= 4, `Detected ${validation.metrics.resumeSectionCount} resume sections (>= 4)`);
assert(validation.metrics.hasContactInfo === true, 'Contact info detected');

// 5. Verify Full Analysis Engine Processing
const analysis = analyseResumeLocally(extractedResumeText, 'Full Stack Software Engineer');
assert(typeof analysis.overallScore === 'number' && analysis.overallScore > 60, `Overall score computed successfully: ${analysis.overallScore}`);
assert(analysis.candidateName === 'Saravan Prasanna', `Candidate name accurately parsed: "${analysis.candidateName}"`);
assert(analysis.diagnostics?.skillsFoundCount >= 8, `Skills parsed accurately: ${analysis.diagnostics?.skillsFoundCount} skills found`);

console.log(`\n========================================`);
console.log(`SUMMARY: ${passed} passed, ${failed} failed.`);
console.log(`========================================\n`);

if (failed > 0) {
  process.exit(1);
}
